<!-- 文件作用：展示服务封面、认证、价格和真实成交数据。 -->
<template><view class="service-card" @click="go('/pages/service/index?id=' + service.id)"><CoverArt :src="service.cover_url" :labels="service.labels"/><view class="service-body"><view class="service-title">{{ service.title }}</view><view class="service-tags"><view v-if="service.club_verified" class="cert"><Icon name="shield" :size="10" />俱乐部认证</view><text v-else class="service-tag">{{ service.category }}</text><text v-for="tag in visibleTags" :key="tag" class="service-tag">{{ tag }}</text></view><view class="service-price"><view><text class="currency">¥</text><text class="amount">{{ money(service.price_cents) }}</text><text class="unit"> / {{ service.unit || '单' }}</text></view><text class="count">{{ service.completed_count || 0 }} 单</text></view><view class="provider"><view class="mini-avatar">{{ (service.provider_name || '玩').slice(0,1) }}</view><text class="truncate">{{ service.provider_name || '独立打手' }}</text><view class="rating"><Icon name="star" :size="9" color="#d5ba7e"/>{{ Number(service.rating || 0).toFixed(1) }}</view></view></view></view></template>
<script setup>
import { computed } from 'vue'
import CoverArt from './CoverArt.vue'
import Icon from './Icon.vue'
import { money, go } from '../lib/format'
const props = defineProps({ service: { type: Object, required: true } })
const visibleTags = computed(() => (props.service.tags || []).filter(tag => !props.service.club_verified || tag !== '俱乐部认证').slice(0, 1))
</script>
<style scoped>.service-card{border:1px solid rgba(255,255,255,.09);background:var(--surface);border-radius:13px;overflow:hidden;cursor:pointer}.service-body{padding:11px 11px 10px}.service-title{font-weight:650;font-size:12px;line-height:1.5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.service-tags{display:flex;gap:4px;height:28px;align-items:center;overflow:hidden;white-space:nowrap}.service-tag,.cert{font-size:8px;background:rgba(255,255,255,.06);padding:2px 5px;border-radius:3px;color:#99aaa0;display:inline-flex;align-items:center;gap:2px}.cert{color:var(--accent);background:rgba(255,255,255,.035)}.service-price{display:flex;justify-content:space-between;align-items:baseline;gap:4px;margin:3px 0 12px}.currency{color:var(--accent);font-size:11px;font-weight:700;margin-right:2px}.amount{color:var(--accent);font-size:23px;font-weight:800;line-height:1;letter-spacing:-.7px}.unit{font-size:8px;color:#819288}.count{font-size:8px;color:#819288;white-space:nowrap}.provider{display:flex;align-items:center;gap:5px;padding-top:9px;border-top:1px solid rgba(255,255,255,.07);font-size:9px;color:#afbbb2;min-width:0}.mini-avatar{display:flex;align-items:center;justify-content:center;height:17px;width:17px;flex-shrink:0;border-radius:50%;background:#35413b;font-size:8px;color:#c9d5cc}.rating{margin-left:auto;color:#c7b17f;display:flex;align-items:center;gap:3px;font-size:8px}
</style>
